#!/usr/bin/env node
// =============================================================================
// tools/custom.mjs: your custom instructions, from one JSON file into the model and the hardware
//
//   node tools/custom.mjs                      custom/instructions.json -> model/custom_spec.js + src/Custom_Unit.sv
//   node tools/custom.mjs --spec my.json       another file (for example one saved from web/custom.html)
//   node tools/custom.mjs --check              exit 1 if the generated files are out of date (CI)
//   node tools/custom.mjs --print              print the SystemVerilog module and change nothing
//
// The same expression is compiled twice by model/custom.js: to JavaScript for the model, to SystemVerilog
// here. `make test` then runs programs/23_custom_instructions.s on the RTL and on the model and compares
// them on every clock cycle, so the two translations are checked against each other.
// =============================================================================
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { validate, verilogModule } from '../model/custom.js';

const ROOT = path.join(path.dirname(fileURLToPath(import.meta.url)), '..');
const args = process.argv.slice(2);
const opt = k => { const i = args.indexOf(k); return i >= 0 ? args[i + 1] : null; };
const specPath = path.resolve(opt('--spec') || path.join(ROOT, 'custom/instructions.json'));

// The names a custom instruction may not take (the standard set; read without the custom ones)
async function standardNames() {
  const src = fs.readFileSync(path.join(ROOT, 'model/isa.js'), 'utf8');
  return [...src.matchAll(/^\s*I\('([a-z0-9.]+)'/gm)].map(m => m[1]);
}

export function loadSpec(file) {
  const raw = JSON.parse(fs.readFileSync(file, 'utf8'));
  return Array.isArray(raw) ? raw : raw.instructions;
}

export function specModule(list) {
  const plain = list.map(c => ({ name: c.name, format: c.format, funct3: c.funct3, ...(c.format === 'R' ? { funct7: c.funct7 } : {}), expr: c.expr, desc: c.desc || '', ...(c.group ? { group: c.group } : {}) }));
  return `// GENERATED by tools/custom.mjs from custom/instructions.json: the custom instructions src/Custom_Unit.sv
// implements. model/isa.js registers them at start-up. Do not edit: change the JSON file and run \`make custom\`.
export default ${JSON.stringify(plain, null, 2)};
`;
}

async function main() {
  const list = loadSpec(specPath);
  const r = validate(list, await standardNames());
  if (!r.ok) {
    for (const e of r.errors) console.error(`${path.relative(process.cwd(), specPath)}: ${e.index >= 0 ? `instruction ${e.index + 1} (${list[e.index]?.name || '?'}), ` : ''}${e.field}: ${e.message}`);
    process.exit(1);
  }
  const outputs = { 'model/custom_spec.js': specModule(r.compiled), 'src/Custom_Unit.sv': verilogModule(r.compiled) };
  if (args.includes('--print')) { process.stdout.write(outputs['src/Custom_Unit.sv']); return; }
  let stale = 0;
  for (const [rel, text] of Object.entries(outputs)) {
    const file = path.join(ROOT, rel), old = fs.existsSync(file) ? fs.readFileSync(file, 'utf8') : null;
    if (old === text) continue;
    if (args.includes('--check')) { console.error(`${rel} is out of date: run make custom`); stale++; continue; }
    fs.writeFileSync(file, text); console.log(`wrote ${rel}`);
  }
  if (stale) process.exit(1);
  console.log(`${r.compiled.length} custom instruction${r.compiled.length === 1 ? '' : 's'}: ${r.compiled.map(c => c.name).join(', ') || 'none'}`);
}
if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) main();
